
import json
import os
import unittest

import joblib
import numpy as np
import pandas as pd


class TestMLPipeline(unittest.TestCase):

    @classmethod
    def setUpClass(cls):
        """Load files generated by train_model.py."""
        cls.dataset_path = "student_results.csv"
        cls.model_path = "student_result_model.pkl"
        cls.metrics_path = "metrics.json"

        cls.dataset = pd.read_csv(cls.dataset_path)

        cls.model = joblib.load(cls.model_path)

        with open(cls.metrics_path, "r") as file:
            cls.metrics = json.load(file)

    def test_dataset_created(self):
        """Check whether the dataset exists."""
        self.assertTrue(os.path.exists(self.dataset_path))
        self.assertGreater(len(self.dataset), 0)

    def test_model_created(self):
        """Check whether the trained model exists."""
        self.assertTrue(os.path.exists(self.model_path))
        self.assertIsNotNone(self.model)

    def test_metrics_created(self):
        """Check whether the metrics file exists."""
        self.assertTrue(os.path.exists(self.metrics_path))
        self.assertIn("accuracy", self.metrics)

    def test_accuracy_is_valid(self):
        """Check that accuracy is between 0 and 1."""
        accuracy = float(self.metrics["accuracy"])
        self.assertGreaterEqual(accuracy, 0.0)
        self.assertLessEqual(accuracy, 1.0)

    def test_model_prediction(self):
        """Check that the model returns a valid binary prediction."""
        student = np.array([[80, 80, 80, 80]])
        prediction = self.model.predict(student)[0]

        self.assertIn(int(prediction), [0, 1])

    def test_high_performance_student(self):
        """A high-performing student should be predicted as PASS (1)."""
        student = np.array([[95, 95, 95, 95]])
        prediction = self.model.predict(student)[0]

        self.assertEqual(int(prediction), 1)

    def test_low_performance_student(self):
        """A low-performing student should be predicted as FAIL (0)."""
        student = np.array([[20, 20, 20, 20]])
        prediction = self.model.predict(student)[0]

        self.assertEqual(int(prediction), 0)


if __name__ == "__main__":
    unittest.main(verbosity=2)
